badExample:
for (auto it = vec.begin(); it != vec.end(); ++it) {
    if (*it == target) vec.erase(it);
}

fixedExample:
for (auto it = vec.begin(); it != vec.end();) {
    if (*it == target) {
        it = vec.erase(it);
    } else {
        ++it;
    }
}

badExample:
void render(Base obj) {
    obj.draw(); // Calls Base::draw, derived sliced
}

fixedExample:
void render(const Base &obj) {
    obj.draw(); // Dispatches dynamically to Derived::draw
}

badExample:
class Base {
public:
    ~Base() {}
};
class Derived : public Base {
    int *data = new int[100];
public:
    ~Derived() { delete[] data; }
};

fixedExample:
class Base {
public:
    virtual ~Base() = default;
};
class Derived : public Base {
    int *data = new int[100];
public:
    ~Derived() override { delete[] data; }
};

