    int factor = 10;
    return [&factor](int x) { return x * factor; }; // factor dies!
}

fixedExample:
auto create_callback() {
    int factor = 10;
    return [factor](int x) { return x * factor; }; // captured by value
}

badExample:
class Holder {
    const std::string &ref;
public:
    Holder(const std::string &s) : ref(s) {}
};
// Invoked as Holder h("temporary"); ref immediately dangles!

fixedExample:
class Holder {
    std::string val;
public:
    Holder(std::string s) : val(std::move(s)) {}
    const std::string& get() const { return val; }
};

badExample:
std::vector<int> v = {10};
int *ptr = &v[0];
v.push_back(20); // reallocation may happen
int val = *ptr; // ptr may be dangling!

fixedExample:
std::vector<int> v;
v.reserve(10); // Guarantee sufficient capacity upfront
v.push_back(10);
int *ptr = &v[0];
v.push_back(20); // No reallocation occurs
int val = *ptr;

